export const onBeforeInput = (e) => {
    switch (e.nativeEvent.data.toLowerCase()) {
        // prevent using some special characters
        case "e":
        case "+": {
            e.preventDefault();
            break;
        }
        // prevent multiple minus signs
        case "-": {
            if (e.target.value.includes("-")) {
                e.preventDefault();
            }
            break;
        }
        default:
            return;
    }
};
